INSERT INTO "EnglishMarathi" VALUES('No pains, no gains (No sweat, no sweets/No rose without thorns)','कष्टेविण फळ नाही. टाकीचे घाव सोसल्याशिवाय देवपण येत नाही. कट्यावाचून गुलाब नाही ',NULL,NULL,NULL);
INSERT INTO "EnglishMarathi" VALUES('No smoke without fire','विस्तावाशिवाय धूर नाही. एखाद्या अफवेमागे बहुधा काहीतरी सत्य असतेच ',NULL,NULL,NULL);
INSERT INTO "EnglishMarathi" VALUES('Old is gold','जुने ते सोने ',NULL,NULL,NULL);
INSERT INTO "EnglishMarathi" VALUES('One good turn deserves another','उपकाराची परतफेड उपकारानेच करावी ',NULL,NULL,NULL);
INSERT INTO "EnglishMarathi" VALUES('One man''s fault is another man''s lesson','पुढच्यास ठेच मागचा शहाणा ',NULL,NULL,NULL);
INSERT INTO "EnglishMarathi" VALUES('One man''s loss is another man''s gain','पंत मेले,राव चढले.एकाची जळते दाढी,दुसरा त्यावर पेटवी विडी.एकाची लागली वाट ,त्यातून दुसऱ्याची भरभराट ',NULL,NULL,NULL);
INSERT INTO "EnglishMarathi" VALUES('One man''s meat is another man''s poison','एकाला हिकारक गोष्ट दुसऱ्याला हानिकारक ठरू शकते एकाला ज्याचे आमिष तेच दुसऱ्याचे विष',NULL,NULL,NULL);
INSERT INTO "EnglishMarathi" VALUES('One nail drives out another','नाक दाबले की तोंड उघडते दबाव टाकला तरच मार्गी लागते',NULL,NULL,NULL);
INSERT INTO "EnglishMarathi" VALUES('One swallow does not make a summer','एखाद्या उदाहरणावरून नियम सिद्ध होत नाही ',NULL,NULL,NULL);
INSERT INTO "EnglishMarathi" VALUES('Out of frying pan, into the fire','आगीतून फुफाट्यात एका संकटातून दुसऱ्या संकटात ',NULL,NULL,NULL);
