INSERT INTO "EnglishMarathi" VALUES('Strike while the iron is hot','तवा तापलेला आहे तोवर त्यावर पोळी भाजून घ्या . वाहत्या गंगेत हात धुऊन घ्या',NULL,NULL,NULL);
