BEGIN TRANSACTION;
CREATE TABLE "EnglishMarathi" (
	`Key`	TEXT,
	`Meaning1`	TEXT,
	`Meaning2`	TEXT,
	`Meaning3`	TEXT,
	`Meaning4`	TEXT
);
CREATE TABLE "MarathiEnglish" (
	`Key`	TEXT,
	`Meaning1`	TEXT,
	`Meaning2`	TEXT,
	`Meaning3`	TEXT,
	`Meaning4`	TEXT,
	`user_id`	INTEGER
, devanagari TEXT, pos TEXT, definition_mr TEXT, source TEXT, is_stem INTEGER DEFAULT 1);
CREATE TABLE user (
	id INTEGER NOT NULL, 
	public_id VARCHAR(50), 
	email VARCHAR(50), 
	password VARCHAR(80), 
	admin BOOLEAN, 
	PRIMARY KEY (id), 
	UNIQUE (public_id), 
	CHECK (admin IN (0, 1))
);
COMMIT;


